import { HOME_ORG, APPLICATION_LABELS, TERMINAL, SCREENING_PROVIDERS, positionOpen, occupiedPlaces, myApplication, visibleApplications, onboardingSteps, applicationNext, addDays, volunteerRequirements, volunteerRequirement } from './recruitment-model.js';
import { today, sharedPassport } from './passport-model.js';

const pathwayLabel = p => p.pathway==='event'?'Try an open event':p.pathway==='conversation'?'Start with a conversation':'Short application';
const stageColor = status => ['active','open'].includes(status)?'sage':['offered','needs-info','onboarding','waitlisted'].includes(status)?'sand':'neutral';
const requirementCompletionLabel = type => ({welcome:'Welcome message',read:'Read or view',sign:'Acknowledge or sign',provide:'Volunteer provides',organization:'Organization confirms',screening:'External background screening'}[type]||'Volunteer completes');
const screeningPhaseLabel = phase => ({'not-started':'Not started','awaiting-volunteer':'Volunteer action needed','volunteer-action-required':'Follow-up needed','awaiting-verification':'Organization verification needed',satisfied:'Satisfied',expired:'Renewal needed'}[phase]||'Not started');
const screeningActionLabel = (step,coordinator) => coordinator
  ? (step.phase==='awaiting-verification'?'Review result':step.phase==='expired'?'Start renewal':'Start screening')
  : (step.phase==='volunteer-action-required'?'Complete follow-up':'Open provider steps');
const addMonths = (date,months=12) => { const value=new Date(`${date}T12:00:00Z`);value.setUTCMonth(value.getUTCMonth()+Number(months));return value.toISOString().slice(0,10); };
const orgById = (ctx,id) => ctx.state.recruitment.organizations.find(o=>o.id===id);
const statusLabel = a => a.status==='offered'&&a.offerUntil<today()?'Offer expired':APPLICATION_LABELS[a.status];
const head = (title,text,action='',eyebrow='A PLACE TO BEGIN. PEOPLE TO BELONG WITH.') => `<div class="page-heading"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1>${text?`<p>${text}</p>`:''}</div><div class="page-actions">${action}</div></div>`;
function orgMark(ctx,org) { return `<span class="recruit-org-mark ${ctx.e(org.color)}">${ctx.e(org.initial)}</span>`; }
export function positionCard(ctx,p) {
  const {state,ui,e,button,badge}=ctx; const org=orgById(ctx,p.orgId); const application=myApplication(state,ui.person,p.id);
  return `<article class="panel recruit-role"><div class="section-heading">${badge(p.mode,org.color)}${badge(pathwayLabel(p))}</div><span class="eyebrow">${e(org.name)}</span><h3>${e(p.title)}</h3><p>${e(p.impact)}</p><div class="recruit-role-time">${ctx.icon('clock')}<span>${e(p.commitment)}</span></div><div class="recruit-role-footer"><span>${application ? e(statusLabel(application)) : p.pathway==='event'?'No ongoing application':`Reply target: ${p.responseDays} days`}</span>${button('Explore role →','rcPosition',`data-id="${e(p.id)}"`,'btn secondary small')}</div></article>`;
}
export function discoveryResults(ctx) {
  const {state,ui,e,button}=ctx;const watchlistOwner=ui.mode==='coordinator'?'coordinator':ui.person;const saved=state.recruitment.saved[watchlistOwner]||[];const q=(ui.discoveryQuery||'').trim().toLowerCase();
  const organizations=state.recruitment.organizations.filter(o=>(!ui.discoverySaved||saved.includes(o.id))&&(!ui.discoveryCause||ui.discoveryCause==='all'||(o.profile?.causes||[o.cause]).includes(ui.discoveryCause))&&(!q||`${o.name} ${o.location} ${o.mission} ${(o.profile?.causes||[o.cause]).join(" ")} ${state.recruitment.positions.filter(p=>p.orgId===o.id&&positionOpen(p)).map(p=>`${p.title} ${p.tasks} ${p.experience}`).join(' ')}`.toLowerCase().includes(q)));
  return `<div class="recruit-org-grid">${organizations.map(o=>{const watched=saved.includes(o.id);const watchlistControl=ui.discoverySaved?button('<span class="recruit-watchlist-symbol" aria-hidden="true">−</span><span class="recruit-watchlist-tooltip" aria-hidden="true">Remove from Watchlist</span>','rcBookmark',`data-id="${e(o.id)}" aria-label="Remove from Watchlist" aria-pressed="true"`,'icon-button recruit-watchlist checked'):watched?'':button('<span class="recruit-watchlist-symbol" aria-hidden="true">+</span><span class="recruit-watchlist-tooltip" aria-hidden="true">Add to Watchlist</span>','rcBookmark',`data-id="${e(o.id)}" aria-label="Add to Watchlist" aria-pressed="false"`,'icon-button recruit-watchlist');return `<article class="panel recruit-org-card"><div class="recruit-org-art ${e(o.color)}">${orgMark(ctx,o)}<span>${e(o.cause)}</span>${ctx.icon('leaf')}</div><div class="recruit-org-body"><span class="eyebrow">${e(o.location)}</span><h2>${e(o.name)}</h2><p>${e(o.mission)}</p><div class="button-row recruit-org-actions">${button('Meet the Organization','rcOrg',`data-id="${e(o.id)}"`,'btn primary')}${watchlistControl}</div></div></article>`;}).join('')||'<div class="panel empty-state"><h2>No organizations match yet.</h2><p>Try a different cause or search. Your Watchlist starts with organizations you choose.</p></div>'}</div>`;
}
function discovery(ctx) {
  const {state,ui,e,button}=ctx;
  const issuer = ui.mode === 'coordinator';
  const city = ctx.platformContext?.cityName || 'Berkeley';
  const hero = issuer ? {
    eyebrow: 'YOUR CITY NETWORK',
    title: 'Meet the Organizations shaping your city',
    description: 'Explore the organizations in your City Network, learn what they do, and see where your missions intersect.',
    steps: ['01 · Explore', '02 · Learn their work', '03 · Find Common Ground', '04 · Collaborate'],
    orbit: 'Your city.<br>Your network.'
  } : {
    eyebrow: `DISCOVER ORGANIZATIONS IN ${e(city).toUpperCase()}`,
    title: 'Help Local Organizations make an Impact.',
    description: '',
    steps: ['01 · Discover Local Organizations', '02 · View Local Impact', '03 · Signal Interest', '04 · Apply', '05 · Contribute'],
    orbit: 'Room for<br>your kind of help.'
  };
  const heading = issuer ? '<h1 class="sr-only">City Network</h1>' : '';
  const heroHeading = issuer ? `<h2>${hero.title}</h2>` : `<h1>${hero.title}</h1>`;
  const orbit = issuer ? `<div class="recruit-hero-orbit" aria-hidden="true">${ctx.icon('people')}<span>${hero.orbit}</span></div>` : '';
  return `${heading}<section class="recruit-hero ${issuer?'recruit-hero-network':'recruit-hero-participant'}"><div><span class="eyebrow">${hero.eyebrow}</span>${heroHeading}${hero.description?`<p>${hero.description}</p>`:''}<div class="recruit-paths">${hero.steps.map(step=>`<span>${step}</span>`).join('')}</div></div>${orbit}</section><form data-form="rcSearch" class="panel recruit-search"><label class="recruit-search-input">Search organizations or roles<input name="query" id="discovery-search" value="${e(ui.discoveryQuery||'')}" placeholder="Food, repair, writing, a neighborhood…"></label><label>Cause<select id="discovery-cause"><option value="all">All causes</option>${[...new Set(state.recruitment.organizations.flatMap(o=>o.profile?.causes||[o.cause]).filter(Boolean))].map(c=>`<option ${ui.discoveryCause===c?'selected':''}>${e(c)}</option>`).join('')}</select></label>${button('Watchlist','rcSaved',`aria-pressed="${!!ui.discoverySaved}" aria-label="${ui.discoverySaved?'Show all organizations':'Show Watchlist'}"`,'btn recruit-watchlist-filter '+(ui.discoverySaved?'primary is-active':'secondary'))}</form><div id="discovery-results" class="discovery-results" aria-live="polite">${discoveryResults(ctx)}</div>${ctx.integratedPlatform?'':'<p class="microcopy">Fictional local organizations for this prototype. Applications and messages stay in this browser.</p>'}`;
}
function organization(ctx) {
  const {state,ui,e,button,badge}=ctx;const o=orgById(ctx,ui.item);if(!o)return '<div class="empty-state">Organization not found.</div>';
  const positions=state.recruitment.positions.filter(p=>p.orgId===o.id&&positionOpen(p));const joined=o.id===HOME_ORG&&ctx.currentPerson().relationship==='member'||state.recruitment.memberships.some(m=>m.personId===ui.person&&m.orgId===o.id);
  return `<button class="back-link" data-action="nav" data-page="discover">← Discover organizations</button>`+head(e(o.name),e(o.mission),ui.mode==='volunteer'?button((state.recruitment.saved[ui.person]||[]).includes(o.id)?'Saved organization':'Save organization','rcBookmark',`data-id="${e(o.id)}"`,'btn secondary'):'')+`<div class="recruit-layout"><div><section class="panel detail-section"><div class="section-heading">${orgMark(ctx,o)}${badge(o.cause,o.color)}</div><h2>A little about us</h2><p>${e(o.description)}</p>${joined?badge('You belong to this organization','sage'):''}<h3 class="prep-title">A supported start</h3><p>${e(o.support)}</p><h3 class="prep-title">Your welcome</h3><p>${e(o.welcome)}</p></section><div class="section-heading"><h2>Ways to get involved</h2><small>${positions.length} open pathways</small></div><div class="recruit-role-grid">${positions.map(p=>positionCard(ctx,p)).join('')||'<section class="panel empty-state">No roles are open right now. Save the organization and check back here.</section>'}</div></div><aside><section class="panel detail-section"><span class="eyebrow">A PERSON, NOT A PORTAL</span><h2>${e(o.contact)}</h2><p>Your volunteer contact</p><p>${e(o.email)}</p><p>Need help applying or a different format? A coordinator can record your application with you, using answers you approve.</p><p class="microcopy">Sample contact details. No email is sent by this prototype.</p></section><section class="panel detail-section"><h3>What happens next?</h3><ol class="recruit-explainer"><li>Choose a role and read its time, support and preparation.</li><li>Send a short application or ask to start a conversation.</li><li>Get a clear reply, then choose whether to accept an offer.</li><li>Meet your buddy and complete a welcome plan together.</li></ol></section></aside></div>`;
}
function position(ctx) {
  const {state,ui,e,button,badge}=ctx;const p=state.recruitment.positions.find(p=>p.id===ui.item);const coordinator=ui.mode==='coordinator';
  if(!p||p.status==='draft'&&(!coordinator||p.orgId!==ui.recruitOrg))return '<div class="empty-state">This role is not published.</div>';
  const o=orgById(ctx,p.orgId);const mine=myApplication(state,ui.person,p.id);const open=positionOpen(p);const manager=coordinator&&ui.recruitOrg===p.orgId;
  const cta=coordinator?'':mine?button(mine.status==='draft'?'Continue draft':'View my application','rcApplication',`data-id="${e(mine.id)}"`,'btn primary'):open?p.pathway==='event'?button('View event & choose a place','activity',`data-id="${e(p.activityId)}"`,'btn primary'):button(p.pathway==='conversation'?'Introduce yourself':'Apply for this role','rcApply',`data-id="${e(p.id)}"`,'btn primary'):badge('Applications closed','sand');
  return button('← '+e(o.name),'rcOrg',`data-id="${e(o.id)}"`,'back-link')+head(e(p.title),e(o.name)+' · '+e(o.location),cta)+`<div class="recruit-layout"><div><section class="panel detail-section"><div class="recruit-org-tags">${badge(p.mode,o.color)}${badge(pathwayLabel(p))}${!open?badge(p.status==='draft'?'Draft preview':'Not accepting new applications','sand'):''}</div><h2>Why this work matters</h2><p>${e(p.impact)}</p><h3 class="prep-title">What you’ll do</h3><p>${e(p.tasks)}</p><h3 class="prep-title">Time & flexibility</h3><p>${e(p.commitment)}</p><h3 class="prep-title">What you bring</h3><p>${e(p.experience)}</p><h3 class="prep-title">What we provide</h3><p>${e(p.support)}</p><p>${e(o.support)}</p></section><section class="panel detail-section"><h2>Your pathway into the team</h2>${p.pathway==='event'?'<p>This is an open event. Choose a place through the existing event flow; no ongoing membership application is required.</p>':`<ol class="recruit-explainer"><li><strong>${pathwayLabel(p)}</strong> · Your interests, availability and one role question. No CV or passport required.</li><li><strong>A human reply</strong> · ${e(o.contact)} aims to reply within ${p.responseDays} calendar days.</li><li><strong>An offer you choose</strong> · Accept only if the role works for you.</li><li><strong>A shared welcome plan</strong> · ${e(p.requirements.map(k=>({welcome:'local welcome',waiver:'participation agreement preview',food:'food packing preparation',driver:'coordinator driving review'}[k])).join(', ')||'Role introduction')}${p.check?', '+e(p.check):''}; then meet your buddy.</li><li><strong>Start with a clear plan</strong> · Activation adds you to this organization. Booking a shift is a separate choice.</li></ol>`}</section></div><aside><section class="panel detail-section"><h2>Before you apply</h2><dl class="passport-facts"><div><dt>Application length</dt><dd>${p.pathway==='event'?'No application':'About 3–5 minutes'}</dd></div><div><dt>Closing date</dt><dd>${e(p.deadline||'Rolling applications')}</dd></div></dl><p>${e(p.commitment)}</p>${cta}<p class="microcopy">An application is an introduction, not a commitment. You can save a draft or withdraw.</p></section><section class="panel detail-section"><h3>Talk to ${e(o.contact)}</h3><p>${e(o.email)}</p><p>Ask for help applying, a conversation, or an alternative format.</p>${!coordinator&&o.id===HOME_ORG?button('Already have training? My passport →','nav','data-page="passport"','text-button'):''}${manager?`<hr><h3>Organization controls</h3>${p.status==='draft'?button('Edit draft','rcEditRole',`data-id="${e(p.id)}"`,'btn secondary'):''}<div class="button-row">${p.status!=='open'?button('Publish / reopen','rcRoleStatus',`data-id="${e(p.id)}" data-status="open"`,'btn primary'):button('Pause applications','rcRoleStatus',`data-id="${e(p.id)}" data-status="paused"`,'btn secondary')}${p.status!=='closed'?button('Close recruitment','rcRoleStatus',`data-id="${e(p.id)}" data-status="closed"`,'text-button'):''}</div>${open&&p.pathway!=='event'?button('Help someone apply','rcAssist',`data-id="${e(p.id)}"`,'text-button'):''}`:''}</section></aside></div>`;
}
function applicationRow(ctx,a) {
  const {state,ui,e,button,badge}=ctx;const p=state.people.find(p=>p.id===a.personId);const next=applicationNext(a);const overdue=['submitted','reviewing'].includes(a.status)&&!a.firstResponseAt&&a.replyBy<today();
  return `<div class="recruit-application-row"><div><span class="eyebrow">${e(ui.mode==='coordinator'?p.name:orgById(ctx,a.orgId).name)}</span><h3>${e(a.position.title)}</h3><p>${e(next[0])} · ${e(next[1])}</p>${overdue?badge('Reply target passed','sand'):''}</div><div>${badge(statusLabel(a),stageColor(a.status))}${button(a.status==='draft'?'Continue draft':'Open application →','rcApplication',`data-id="${e(a.id)}"`,'btn secondary small')}</div></div>`;
}
function applications(ctx) {
  const {state,ui,e,button,badge,dateLabel}=ctx;
  const applications=visibleApplications(state,ui.person);
  const invitations=(state.recruitment.invitations||[]).filter(invitation=>invitation.personId===ui.person&&invitation.status==='pending'&&(!invitation.kind||invitation.kind==='role'));
  const commitments=state.commitments
    .filter(commitment=>commitment.personId===ui.person&&['confirmed','proposed','waitlisted','verified'].includes(commitment.status))
    .map(commitment=>({commitment,activity:state.activities.find(activity=>activity.id===commitment.activityId)}))
    .filter(item=>item.activity?.date&&!item.activity.archived)
    .sort((a,b)=>(a.activity.date||'').localeCompare(b.activity.date||''));
  const invitationRows=invitations.map(invitation=>{const position=state.recruitment.positions.find(position=>position.id===invitation.positionId);const org=orgById(ctx,invitation.orgId);return `<div class="recruit-application-row"><div><span class="eyebrow">${e(org.name)}</span><h3>${e(position.title)}</h3><p>${e(invitation.message||'The organization invited you to learn more about this role.')}</p></div><div>${badge('Role invitation','sage')}${button('View Role →','rcPosition',`data-id="${e(position.id)}"`,'btn primary small')}</div></div>`;}).join('');
  const commitmentRows=commitments.map(({commitment,activity})=>{
    const typeLabel={event:'One-Time Activity',shift:'Recurring Activity',project:'Program Task'}[activity.type]||'Volunteer Activity';
    const statusLabel={confirmed:'Confirmed',proposed:'Invitation',waitlisted:'Waitlisted',verified:'Verified contribution'}[commitment.status]||commitment.status;
    const statusTone=['confirmed','verified'].includes(commitment.status)?'sage':'sand';
    const actions=commitment.status==='proposed'
      ? `<div class="button-row">${button('Accept','respond',`data-id="${e(commitment.id)}" data-accept="yes"`,'btn primary small')}${button('Decline','respond',`data-id="${e(commitment.id)}" data-accept="no"`,'btn secondary small')}</div>`
      : button('View Activity →','activity',`data-id="${e(activity.id)}"`,'btn secondary small');
    return `<div class="volunteer-commitment-row"><div class="date-block"><small>${dateLabel(activity.date,{month:'short'})}</small><strong>${dateLabel(activity.date,{day:'numeric'})}</strong><span>${dateLabel(activity.date,{weekday:'short'})}</span></div><div class="volunteer-commitment-info"><span class="eyebrow">${e(typeLabel)}</span><h3>${button(e(activity.title),'activity',`data-id="${e(activity.id)}"`,'title-button')}</h3><p>${e(activity.time)} · ${e(activity.location)}</p></div><div class="volunteer-commitment-actions">${badge(statusLabel,statusTone)}${actions}</div></div>`;
  }).join('');
  const pageHeader=`<section class="recruit-hero volunteer-opportunities-hero"><div><span class="eyebrow">YOUR VOLUNTEER ACTIVITY</span><h1>My Volunteering</h1><p>Keep applications, invitations, and the plans you have accepted in one place.</p></div></section>`;
  const commitmentCard=`<section class="panel detail-section recruit-management-card volunteer-journey-card"><div class="recruit-card-header volunteer-commitments"><div><span class="eyebrow">PLANS YOU HAVE MADE</span><h2>Commitments</h2></div>${badge(`${commitments.length} ${commitments.length===1?'activity':'activities'}`,'sage')}</div><div class="recruit-card-body volunteer-journey-body">${commitmentRows||'<div class="empty-state compact"><h3>Your calendar has room.</h3><p>When you accept an activity or receive an invitation, it will appear here.</p></div>'}</div></section>`;
  const applicationCard=`<section class="panel detail-section recruit-management-card volunteer-journey-card"><div class="recruit-card-header volunteer-applications"><div><span class="eyebrow">PATHWAYS INTO AN ORGANIZATION</span><h2>Applications &amp; Role Invitations</h2></div>${badge(`${applications.length+invitations.length} record${applications.length+invitations.length===1?'':'s'}`,'sand')}</div><div class="recruit-card-body volunteer-journey-body">${invitationRows}${applications.length?applications.map(application=>applicationRow(ctx,application)).join(''):invitations.length?'':'<div class="empty-state compact"><h3>Start with a mission that matters to you.</h3><p>Role invitations and applications will appear here before they become commitments.</p></div>'}</div></section>`;
  return pageHeader+`<div class="volunteer-journey">${commitmentCard}${applicationCard}</div>`;
}
function recruitment(ctx) {
  const {state,ui,e,button,badge}=ctx;
  const org=orgById(ctx,ui.recruitOrg);
  if(!org)return '<section class="panel empty-state"><h2>Your organization workspace is loading.</h2><p>Recruitment and onboarding will appear when the signed-in organization is available.</p></section>';
  const applications=visibleApplications(state,'coordinator',org.id);
  const roles=state.recruitment.positions.filter(p=>p.orgId===org.id);
  const requirements=volunteerRequirements(state,org.id);
  const applicationLaneRows=(items,emptyTitle,emptyText)=>items.length?items.map(a=>applicationRow(ctx,a)).join(''):`<div class="empty-state compact"><h3>${emptyTitle}</h3><p>${emptyText}</p></div>`;
  const roleRows=roles.length
    ? roles.map(p=>{
      const programName=p.programId?state.programWorkspace?.programs.find(program=>program.id===p.programId)?.name||'Program':'';
      return `<div class="recruit-application-row"><div><h3>${e(p.title)}</h3><p>Program: ${e(programName||'General')}</p></div><div>${badge(p.status,stageColor(p.status))}${button(p.status==='draft'?'Preview role':'Manage role','rcPosition',`data-id="${e(p.id)}"`,'btn secondary small')}</div></div>`;
    }).join('')
    : '<div class="empty-state compact"><h3>No volunteer positions yet.</h3><p>Create a role to begin accepting applications.</p></div>';
  const requirementRows=requirements.map(requirement=>{
    const assigned=roles.filter(role=>(role.requirements||[]).includes(requirement.id));
    const document=requirement.documentId&&state.documentLibrary?.items?.find(item=>item.id===requirement.documentId);
    const screeningMeta=requirement.completionType==='screening'?`${requirement.providerName} · renew every ${requirement.validMonths} months`:'';
    const meta=[requirementCompletionLabel(requirement.completionType),screeningMeta,document?document.title:'',assigned.length?`Used by ${assigned.map(role=>role.title).join(', ')}`:'Not assigned to a role'].filter(Boolean).map(e).join(' · ');
    const action=requirement.id==='welcome'
      ? button(org.welcomeMessageCreated?'Edit Welcome Message':'Create Welcome Message','rcWelcome','',`btn ${org.welcomeMessageCreated?'secondary':'primary'} small`)
      : button('Edit','rcRequirement',`data-id="${e(requirement.id)}"`,'btn secondary small');
    return `<div class="recruit-requirement-row"><span class="check-circle">${ctx.icon(requirement.owner==='coordinator'?'people':'check')}</span><div><h3>${e(requirement.title)}</h3><p>${e(requirement.id==='welcome'?(org.welcomeMessageCreated?org.welcome:'Create the message every volunteer will read before onboarding.'):requirement.detail)}</p><small>${meta}</small></div>${action}</div>`;
  }).join('');
  const tab=ui.recruitmentTab==='applications'?'applications':'setup';
  const tabs=[['setup','Onboarding Setup'],['applications','Application Management']];
  const recruitmentHeader=`<section class="panel recruitment-detail-header"><div class="recruitment-detail-heading"><div><span class="eyebrow">RECRUITMENT &amp; ONBOARDING</span><h1>Build the welcome. Guide every applicant forward.</h1></div></div><nav class="tabs recruitment-tabs" aria-label="Recruitment and onboarding sections">${tabs.map(([key,label])=>button(label,'rcTab',`data-tab="${key}" aria-pressed="${tab===key}"`,`tab ${tab===key?'active':''}`)).join('')}</nav></section>`;
  if(tab==='setup') return recruitmentHeader+`<div class="recruitment-setup-sequence"><section class="panel detail-section recruit-management-card recruit-requirements-card"><div class="recruit-card-header requirements"><div><span class="eyebrow">01 · DEFINE THE CHECKLIST</span><h2>Volunteer Requirements</h2></div>${button('+ Add Requirement','rcRequirement','','btn primary small')}</div><div class="recruit-card-body recruit-requirements-body"><p class="recruit-requirements-intro">Build reusable onboarding steps for each role. Present guidance, collect an acknowledgement, request information, record an organization review, or coordinate an external background screening without storing its sensitive report in MyCity.</p><div class="recruit-requirement-list">${requirementRows}</div></div></section><section class="panel detail-section recruit-management-card"><div class="recruit-card-header positions"><div><span class="eyebrow">02 · OPEN A PATHWAY</span><h2>Volunteer Roles</h2></div>${button('+ Create Volunteer Role','rcCreateRole','','btn primary small')}</div><div class="recruit-card-body">${roleRows}</div></section></div>`;
  const passportApplications=applications.filter(application=>application.source==='passport-invite');
  const publicApplications=applications.filter(application=>!['passport-invite','invite-link'].includes(application.source));
  const linkApplications=applications.filter(application=>application.source==='invite-link');
  const passportInvitations=(state.recruitment.invitations||[]).filter(invitation=>invitation.orgId===org.id&&['pending','contacted'].includes(invitation.status));
  const passportInvitationRows=passportInvitations.map(invitation=>{
    const person=state.people.find(item=>item.id===invitation.personId);
    if(invitation.kind==='activity'){
      const activity=state.activities.find(item=>item.id===invitation.activityId);
      return `<div class="recruit-application-row"><div><span class="eyebrow">${e(person?.name||'Volunteer')} · ACTIVITY INVITATION</span><h3>${e(activity?.title||'Volunteer activity')}</h3><p>Waiting for the volunteer to accept or decline. This does not add them to the roster.</p></div><div>${badge('Awaiting response','sand')}${button('Open Activity','activity',`data-id="${e(invitation.activityId)}"`,'btn secondary small')}</div></div>`;
    }
    if(invitation.kind==='conversation')return `<div class="recruit-application-row"><div><span class="eyebrow">${e(person?.name||'Volunteer')} · CONVERSATION</span><h3>Passport outreach</h3><p>Message sent. No role, activity, or roster place has been assigned.</p></div><div>${badge('Contacted','sage')}${button('Open Messages','nav','data-page="messages"','btn secondary small')}</div></div>`;
    const role=roles.find(item=>item.id===invitation.positionId);
    return `<div class="recruit-application-row"><div><span class="eyebrow">${e(person?.name||'Volunteer')} · ROLE INVITATION</span><h3>${e(role?.title||'Volunteer role')}</h3><p>Waiting for the volunteer to choose whether to begin an application.</p></div><div>${badge('Awaiting response','sand')}${button('View Passport','ppPublic',`data-person="${e(invitation.personId)}"`,'btn secondary small')}</div></div>`;
  }).join('');
  const engagementCard=(kind,eyebrow,title,description,content,action='')=>`<section class="panel detail-section recruit-management-card engagement-lane"><div class="recruit-card-header ${kind}"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${action}</div><div class="recruit-card-body engagement-lane-body"><p class="recruit-lane-intro">${description}</p>${content}</div></section>`;
  const interestGroups=`<div class="recruit-interest-groups"><section><div class="recruit-interest-heading"><span class="eyebrow">ORGANIZATION OUTREACH</span><h3>Passport Invitations</h3><p>People your organization contacted through the Volunteer Portal. They choose whether to continue before review or onboarding begins.</p></div>${passportInvitationRows+applicationLaneRows(passportApplications,'No accepted Passport invitations yet.','Browse the Volunteer Portal and invite someone to explore a role.')}</section><section><div class="recruit-interest-heading"><span class="eyebrow">VOLUNTEER INTEREST</span><h3>Public Applications</h3><p>People who approached your organization through a public role. Open a record to request information, make an offer, and complete onboarding.</p></div>${applicationLaneRows(publicApplications,'No public applications yet.','Open roles appear through the organization profile and City Network.')}</section></div>`;
  return recruitmentHeader+`<div class="recruitment-engagement-lanes">${engagementCard('invite-links','DIRECT INVITATION','Invite Volunteers','People who responded through your organization’s Volunteer Invite Link enter the General Volunteer pathway. Open their record to use the same review and onboarding process.',applicationLaneRows(linkApplications,'No invite-link responses yet.','Share your Volunteer Invite Link with a person or group you would like to welcome.'),button('Volunteer Invite Link','share','','btn secondary small'))}${engagementCard('combined-interest','ORGANIZATION &amp; VOLUNTEER INITIATED','Interest & Passport Invitations','Manage outreach started by your organization and interest started by volunteers in one place.',interestGroups,button('Volunteer Portal','nav','data-page="passport"','btn secondary small'))}</div>`;
}
function onboardingStepRow(ctx,a,p,step,coordinator) {
  const {e,button,badge}=ctx;
  if(step.completionType!=='screening')return `<div class="recruit-step"><span class="check-circle ${step.done?'done':''}">${ctx.icon(step.done?'check':'clock')}</span><div><strong>${e(step.title)}</strong><small>${step.owner==='coordinator'?e(a.contact):e(p.name)} has this step</small><p>${e(step.detail)}</p>${a.completed[step.key]?`<small>${e(a.completed[step.key].by)} · ${e(a.completed[step.key].note)}</small>`:''}</div>${step.done?badge(step.portable?'Passport accepted':'Complete','sage'):(coordinator?step.owner==='coordinator':step.owner==='volunteer')?button('Open step','rcStep',`data-id="${e(a.id)}" data-key="${e(step.key)}"`,'btn secondary small'):badge('Waiting','sand')}</div>`;
  const hasAction=!step.done&&(coordinator?step.owner==='coordinator':step.owner==='volunteer');
  const phaseTone=step.done?'sage':['awaiting-verification','expired','volunteer-action-required'].includes(step.phase)?'sand':'neutral';
  return `<div class="recruit-step recruit-screening-step"><span class="check-circle ${step.done?'done':''}">${ctx.icon(step.done?'check':'work')}</span><div><strong>${e(step.title)}</strong><small>${e(step.screening.providerName)} · ${e(screeningPhaseLabel(step.phase))}</small><p>${e(step.detail)}</p>${step.done?`<small>Verified ${e(step.completed.verifiedAt)} · valid through ${e(step.completed.expiresAt)} · private MyPassport credential</small>`:step.attempt?.note?`<small>Latest update: ${e(step.attempt.note)}</small>`:''}</div>${hasAction?button(screeningActionLabel(step,coordinator),'rcStep',`data-id="${e(a.id)}" data-key="${e(step.key)}"`,'btn secondary small'):badge(step.done?'Satisfied':screeningPhaseLabel(step.phase),phaseTone)}</div>`;
}
function application(ctx) {
  const {state,ui,e,button,badge}=ctx;const coordinator=ui.mode==='coordinator';const a=visibleApplications(state,coordinator?'coordinator':ui.person,ui.recruitOrg).find(a=>a.id===ui.item);
  if(!a)return '<section class="panel empty-state">This application is private or belongs to another recruitment workspace.</section>';
  const org=orgById(ctx,a.orgId);const p=state.people.find(p=>p.id===a.personId);const [who,next]=applicationNext(a);const canReview=coordinator&&['submitted','reviewing','needs-info','waitlisted','offered'].includes(a.status);const steps=onboardingSteps(state,a);const ready=steps.every(s=>s.done);
  return button('← '+(coordinator?'Recruitment':'My Volunteering'),'nav',`data-page="${coordinator?'recruitment':'applications'}"`,'back-link')+head(e(a.position.title),`${e(org.name)} · ${e(p.name)}`,badge(statusLabel(a),stageColor(a.status)))+`<div class="recruit-layout"><div><section class="recruit-next"><span class="eyebrow">THE NEXT STEP BELONGS TO ${e(who).toUpperCase()}</span><h2>${e(next)}</h2>${!coordinator&&a.status==='draft'?button('Continue draft','rcApply',`data-id="${e(a.positionId)}"`,'btn primary'):''}${!coordinator&&a.status==='offered'?`<div class="button-row">${a.offerUntil>=today()?button('Accept role offer','rcAcceptOffer',`data-id="${e(a.id)}"`,'btn primary'):''}${button('Decline offer','rcDecision',`data-id="${e(a.id)}" data-decision="declineOffer"`,'btn secondary')}</div>`:''}${canReview?`<div class="button-row">${['reviewing','needs-info','waitlisted','offered','declined'].map(status=>button({reviewing:'Start review','needs-info':'Ask a question',waitlisted:'Waitlist',offered:a.status==='offered'?'Renew offer':'Offer a place',declined:'Decline with feedback'}[status],'rcDecision',`data-id="${e(a.id)}" data-decision="${status}"`,status==='offered'?'btn primary':'btn secondary')).join('')}</div>`:''}${coordinator&&a.status==='onboarding'?button('Activate volunteer role','rcActivate',`data-id="${e(a.id)}" ${ready?'':'disabled'}`,'btn primary'):''}${a.status==='active'?`<p><strong>Your buddy:</strong> ${e(a.buddy)}<br><strong>First step:</strong> ${e(a.firstStep)}</p>${!coordinator&&a.orgId===HOME_ORG&&a.position.activityId?button('Choose your first activity →','activity',`data-id="${e(a.position.activityId)}"`,'btn primary'):''}`:''}</section>${['onboarding','active'].includes(a.status)?`<section class="panel detail-section"><div class="section-heading"><h2>Your shared welcome plan</h2>${badge(`${steps.filter(s=>s.done).length} / ${steps.length} ready`,'sage')}</div><p>${e(org.welcome)}</p>${steps.map(step=>onboardingStepRow(ctx,a,p,step,coordinator)).join('')}${a.orgId===HOME_ORG?button(coordinator?'Review shared passport →':'Reuse training from my passport →','rcPassport',`data-person="${e(a.personId)}"`,'text-button'):''}</section>`:''}<section class="panel detail-section"><h2>The application</h2><dl class="recruit-answers"><dt>Why this interests me</dt><dd>${e(a.answers.motivation||'Draft not yet completed')}</dd><dt>Availability</dt><dd>${e(a.answers.availability)}</dd><dt>Experience or things I enjoy · optional</dt><dd>${e(a.answers.experience||'Not added')}</dd>${a.position.question?`<dt>${e(a.position.question)}</dt><dd>${e(a.answers.answer)}</dd>`:''}<dt>Reply email</dt><dd>${e(a.answers.email)}</dd></dl><p class="microcopy">${a.assisted?'Entered with the volunteer’s approval. ':''}${a.status==='draft'||!a.submittedAt?'This private draft is visible only to you.':'This application is shared only with the receiving organization.'} Passport access is a separate choice.</p></section>${a.status!=='draft'?`<section class="panel detail-section"><h2>Keep the conversation here</h2><div class="conversation">${a.messages.map(m=>`<div class="message"><div><strong>${e(m.by)} <small>${e(m.date)}</small></strong><p>${e(m.text)}</p></div></div>`).join('')||'<p class="muted">Ask a question or share what would help you get started.</p>'}</div><form data-form="rcMessage" data-id="${e(a.id)}"><label>Your message<textarea name="note" required maxlength="1200"></textarea></label><button type="submit" class="btn primary">Add message</button>${ctx.errorOutput()}</form><p class="microcopy">Visible in this application. No external email or notification is sent.</p></section>`:''}</div><aside><section class="panel detail-section"><h3>Your contact</h3><p><strong>${e(a.contact)}</strong><br>${e(org.email)}</p><h3 class="prep-title">What you applied for</h3><p>${e(a.position.commitment)}</p><p>${e(a.position.support)}</p><p class="microcopy">Role details are saved with your application. Later recruitment changes do not silently change your offer.</p></section><section class="panel detail-section"><h3>Application timeline</h3><ol class="recruit-timeline">${a.history.slice().reverse().map(h=>`<li><strong>${e(APPLICATION_LABELS[h.status])}</strong><p>${e(h.note)}</p><small>${e(h.by)} · ${e(h.date)}</small></li>`).join('')||'<li>Private draft · only you can see it.</li>'}</ol></section>${!coordinator&&![...TERMINAL,'active'].includes(a.status)?`<section class="panel detail-section"><h3>It is always your choice.</h3><p>You can withdraw this application. Other memberships and commitments stay as they are.</p>${button('Withdraw application','rcDecision',`data-id="${e(a.id)}" data-decision="withdraw"`,'text-button danger')}</section>`:''}</aside></div>`;
}
export function renderRecruitment(ctx) {
  switch(ctx.ui.page){case'discover':return discovery(ctx);case'org-profile':return organization(ctx);case'position':return position(ctx);case'applications':return applications(ctx);case'application':return application(ctx);case'recruitment':return recruitment(ctx);}
}

export function recruitmentDialog(ctx,type,data={}) {
  const {state,ui,e,button,errorOutput}=ctx;const r=state.recruitment;const org=orgById(ctx,ui.recruitOrg);
  const form=(title,body,label,attrs='',extra='')=>({title,content:`<form data-form="rc${type}" ${attrs}><div class="dialog-body">${body}${errorOutput()}</div><div class="dialog-footer">${button('Cancel','close','','btn secondary')}${extra}<button type="submit" class="btn primary" name="intent" value="submit">${label}</button></div></form>`});
  if(type==='Interest') {
    const position=r.positions.find(position=>position.id===data.id);const receiving=position&&orgById(ctx,position.orgId);const person=ctx.currentPerson();
    if(!position||!receiving)return null;
    const alreadyShared=Boolean(sharedPassport(state,person.id,receiving.id));
    return form('Signal interest in this role',`<div class="recruit-interest-confirm"><span>${ctx.icon('people')}</span><div><span class="eyebrow">${e(receiving.name)}</span><h3>${e(position.title)}</h3><p>Let the organization know you are interested without starting an application or accepting a commitment.</p></div></div><div class="callout sage"><strong>${alreadyShared?'Your MyPassport is already shared':'Your confirmation shares MyPassport'}</strong><p>${alreadyShared?'Your current organization-specific Passport access will remain active.':'The organization will receive your profile, email, availability, volunteering preferences, and current Passport records for up to one year.'}</p></div><p class="microcopy">You can end Passport access later from MyPassport. The organization can invite you to apply, ask a question, or suggest a next step.</p>`,'Share MyPassport & Signal Interest',`data-position="${e(position.id)}" data-org="${e(receiving.id)}"`);
  }
  if(type==='Apply'||type==='Assist') {
    const position=r.positions.find(p=>p.id===data.id);const p=type==='Assist'?state.people.find(p=>p.id===(data.person||'robin')):ctx.currentPerson();const existing=myApplication(state,p.id,position.id);const a=existing?.answers||{email:p.email,availability:p.availability==='Not shared yet'?'':p.availability,experience:type==='Assist'?'':state.passports.profiles[p.id]?.skills||''};
    return form(type==='Assist'?'Apply together':position.pathway==='conversation'?'Start a conversation':'A short introduction',`<p><strong>${e(position.title)}</strong><br>${e(orgById(ctx,position.orgId).name)} · Reply target ${position.responseDays} calendar days</p>${type==='Assist'?`<label>Volunteer<select id="assisted-person" data-position="${e(position.id)}">${state.people.map(v=>`<option value="${e(v.id)}" ${v.id===p.id?'selected':''}>${e(v.name)}</option>`).join('')}</select></label>`:`<p>Applying as <strong>${e(p.name)}</strong>. You can review and change the details below before sending.</p>`}<label>Reply email<input name="email" type="email" value="${e(a.email)}" maxlength="200"></label><label>What interests you about helping?<textarea name="motivation" maxlength="1200">${e(a.motivation||'')}</textarea></label><label>When could volunteering fit?<input name="availability" value="${e(a.availability)}" maxlength="300"></label><label>Experience or things you enjoy · optional<textarea name="experience" maxlength="1200">${e(a.experience||'')}</textarea></label>${position.question?`<label>${e(position.question)}<textarea name="answer" maxlength="1200">${e(a.answer||'')}</textarea></label>`:''}<label class="recruit-consent"><input name="consent" type="checkbox"><span>${type==='Assist'?'The volunteer asked for help applying and approved these answers and sharing choices.':'Send these answers and my name to this organization so it can reply about this role.'}</span></label><p class="microcopy">No CV or passport required. Don’t include identity documents, medical details, or background-check reports. Your other applications and passport stay separate.</p>`,'Send application',`data-position="${e(position.id)}" data-person="${e(p.id)}" novalidate`,type==='Assist'?'':'<button type="submit" name="intent" value="draft" class="btn secondary">Save private draft</button>');
  }
  if(type==='Role') {
    const p=r.positions.find(p=>p.id===data.id)||{requirements:['welcome','waiver'],capacity:3,responseDays:5,mode:'In person',pathway:'application',programId:data.program||''};
    const linkedProgram=state.programWorkspace?.programs.find(program=>program.id===p.programId);
    const assignablePrograms=(state.programWorkspace?.programs||[]).filter(program=>!['complete','archived'].includes(program.status));
    const programField=p.id?`<label>Assign to Program<select name="programId"><option value="">General · no program</option>${assignablePrograms.map(program=>`<option value="${e(program.id)}" ${program.id===p.programId?'selected':''}>${e(program.name)}</option>`).join('')}</select><small>Program roles appear within that program as well as Volunteer Recruitment.</small></label>`:`<input type="hidden" name="programId" value="${e(p.programId||'')}">`;
    const input=(label,name,value='',required=true)=>`<label>${label}<input name="${name}" value="${e(value)}" ${required?'required':''} maxlength="300"></label>`;
    const textarea=(label,name,value='',required=true)=>`<label>${label}<textarea name="${name}" ${required?'required':''} maxlength="1200">${e(value)}</textarea></label>`;
    if (linkedProgram) {
      return form(p.id?'Edit Program Role':'Create Program Role', `${programField}${input('Role title','title',p.title)}${textarea('Role Description','tasks',p.tasks)}<label>Work mode<select name="mode">${['In person','Remote','Hybrid'].map(m=>`<option ${m===p.mode?'selected':''}>${m}</option>`).join('')}</select></label>`, p.id?'Save Role':'Create Role', `data-id="${e(p.id||'')}" data-program="${e(linkedProgram.id)}" data-source="${e(data.source||'')}"`);
    }
    return form('Design a welcoming volunteer role',`<p>${e(org.name)}${linkedProgram?` · ${e(linkedProgram.name)}`:''} · Save a draft, review the public preview, then publish.</p>${programField}${input('Role title','title',p.title)}${textarea('The difference this role makes','impact',p.impact)}${textarea('What the volunteer will do','tasks',p.tasks)}${input('Time, duration and flexibility','commitment',p.commitment)}${textarea('Experience needed / what can be learned','experience',p.experience)}${textarea('Support, equipment and access options','support',p.support)}<div class="form-grid"><label>Work mode<select name="mode">${['In person','Remote','Hybrid'].map(m=>`<option ${m===p.mode?'selected':''}>${m}</option>`).join('')}</select></label><label>Application pathway<select name="pathway"><option value="application" ${p.pathway==='application'?'selected':''}>Short application</option><option value="conversation" ${p.pathway==='conversation'?'selected':''}>Conversation first</option></select></label><label>New volunteer places<input name="capacity" type="number" min="1" max="100" required value="${p.capacity}"></label><label>Initial reply target · calendar days<input name="responseDays" type="number" min="1" max="30" required value="${p.responseDays}"></label></div>${input('One role-specific question · optional','question',p.question,false)}<label>Application closing date · optional<input type="date" name="deadline" min="${today()}" value="${e(p.deadline)}"></label><fieldset class="passport-choices"><legend>Volunteer requirements</legend>${volunteerRequirements(state,org.id).map(requirement=>`<label><input name="requirements" type="checkbox" value="${e(requirement.id)}" ${p.requirements.includes(requirement.id)?'checked':''}><span>${e(requirement.title)}</span></label>`).join('')}</fieldset>${input('Additional coordinator check · optional','check',p.check,false)}<p class="microcopy">Manage reusable checklist steps from Volunteers → Recruitment & Onboarding. A buddy introduction and first-step discussion are included in every onboarding plan.</p>${org.id===HOME_ORG?`<label>Suggested first activity · optional<select name="activityId"><option value="">Agree one together</option>${state.activities.filter(a=>!linkedProgram||a.programId===linkedProgram.id).map(a=>`<option value="${e(a.id)}" ${a.id===p.activityId?'selected':''}>${e(a.title)}</option>`).join('')}</select></label>`:''}`,'Save role draft',`data-id="${e(p.id||'')}" data-program="${e(p.programId||'')}" data-source="${e(data.source||'')}"`);
  }
  if(type==='Requirement') {
    const requirement=data.id?volunteerRequirement(state,org.id,data.id):null;
    const roles=r.positions.filter(position=>position.orgId===org.id);
    const assigned=new Set(requirement?roles.filter(position=>(position.requirements||[]).includes(requirement.id)).map(position=>position.id):[]);
    const roleChoices=roles.map(position=>{const program=position.programId&&state.programWorkspace?.programs.find(item=>item.id===position.programId);return `<label><input type="checkbox" name="positionIds" value="${e(position.id)}" ${assigned.has(position.id)?'checked':''}><span><strong>${e(position.title)}</strong><small>${program?e(program.name):'Organization role'}</small></span></label>`;}).join('')||'<p class="muted">Create a volunteer role before assigning this requirement.</p>';
    const documents=state.documentLibrary?.items||[];
    const completionType=requirement?.completionType||'read';
    const documentOptions=documents.map(document=>`<option value="${e(document.id)}" ${document.id===requirement?.documentId?'selected':''}>${e(document.title)} · ${e(document.category)}</option>`).join('');
    const screeningProvider=requirement?.screeningProvider||'checkr';
    const startMethod=requirement?.startMethod||'organization-invite';
    const screeningFields=`<section class="requirement-screening-fields" data-screening-fields ${completionType==='screening'?'':'hidden'}><div class="requirement-screening-intro"><strong>External provider, manual verification</strong><p>MyCity coordinates the steps and status. The volunteer enters identity details only in the provider’s system, and your organization reviews the result there.</p></div><div class="form-grid"><label>Screening provider<select name="screeningProvider">${Object.entries(SCREENING_PROVIDERS).map(([key,label])=>`<option value="${e(key)}" ${key===screeningProvider?'selected':''}>${e(label)}</option>`).join('')}</select></label><label>Provider name · for Other<input name="providerName" maxlength="120" value="${e(requirement?.providerName||'')}"></label><label>How screening begins<select name="startMethod"><option value="organization-invite" ${startMethod==='organization-invite'?'selected':''}>Organization sends provider invitation</option><option value="volunteer-link" ${startMethod==='volunteer-link'?'selected':''}>Volunteer opens a standard provider link</option><option value="live-scan" ${startMethod==='live-scan'?'selected':''}>Volunteer follows Live Scan instructions</option></select></label><label>Who pays the provider?<select name="payer"><option value="organization" ${requirement?.payer!=='volunteer'?'selected':''}>Organization</option><option value="volunteer" ${requirement?.payer==='volunteer'?'selected':''}>Volunteer</option></select></label><label>Volunteer start or location link<input type="url" name="volunteerUrl" maxlength="500" value="${e(requirement?.volunteerUrl||'')}" placeholder="https://…"></label><label>Organization review portal · optional<input type="url" name="organizationUrl" maxlength="500" value="${e(requirement?.organizationUrl||'')}" placeholder="https://…"></label><label>Renew after<input type="number" name="validMonths" min="1" max="60" value="${e(requirement?.validMonths||12)}"><small>Months after organization verification.</small></label></div><div class="callout sand"><strong>Keep sensitive data with the provider</strong><p>Do not upload reports, Social Security numbers, fingerprints, dates of birth, ID images, or offense details to MyCity. Record only whether this role requirement is satisfied, its review date, and expiration.</p></div></section>`;
    return form(requirement?'Edit Volunteer Requirement':'Add Volunteer Requirement',`<p>Define one clear step, the response you need, and the roles it applies to.</p><label>Requirement Name<input name="title" required maxlength="120" value="${e(requirement?.title||'')}"></label><label>What needs to happen?<select name="completionType" id="requirement-completion"><option value="read" ${completionType==='read'?'selected':''}>Read or view information</option><option value="sign" ${completionType==='sign'?'selected':''}>Acknowledge or sign a document</option><option value="provide" ${completionType==='provide'?'selected':''}>Provide information or a file</option><option value="organization" ${completionType==='organization'?'selected':''}>Organization confirms completion</option><option value="screening" ${completionType==='screening'?'selected':''}>External background screening</option></select></label><div class="requirement-type-guide"><div><strong>Read</strong><span>Present guidance before the volunteer continues.</span></div><div><strong>Sign</strong><span>Record agreement to the selected document.</span></div><div><strong>Provide</strong><span>Ask the volunteer for information or evidence.</span></div><div><strong>Confirm</strong><span>Let an organization member record a local review or training.</span></div><div><strong>Screen</strong><span>Coordinate an external provider and manually verify the result.</span></div></div>${screeningFields}<label data-requirement-document ${completionType==='screening'?'hidden':''}>Document or template<select name="documentId" id="requirement-document"><option value="">No linked document</option>${documentOptions}</select><small>Required for acknowledgement or signature. Optional as guidance or a template for other requirement types.</small></label><label>Instructions for the volunteer or reviewer<textarea name="detail" required maxlength="800" rows="4">${e(requirement?.detail||'')}</textarea></label><fieldset class="passport-choices recruit-role-requirements"><legend>Required for Roles</legend>${roleChoices}</fieldset><p class="microcopy">Future applicants receive this version of the requirement; people already onboarding keep the checklist already shared with them.</p>`,'Save Requirement',`data-id="${e(requirement?.id||'')}"`);
  }
  if(type==='Welcome')return form(org.welcomeMessageCreated?'Edit Welcome Message':'Create Welcome Message',`<p>This is the first organization-specific message every volunteer reads. Explain who you are, what they can expect, where to get help, and how to raise a concern.</p><label>Welcome Message<textarea name="welcome" required maxlength="1600" rows="9" placeholder="Welcome to our organization…">${e(org.welcome||'')}</textarea></label><p class="microcopy">Keep role-specific instructions in the role or another volunteer requirement.</p>`,org.welcomeMessageCreated?'Save Welcome Message':'Create Welcome Message');
  if(type==='Decision') {
    const labels={reviewing:'Start the review', 'needs-info':'Ask a role-related question',waitlisted:'Offer a place on the waiting list',offered:'Offer a volunteer role',declined:'Close with useful feedback',withdraw:'Withdraw your application',declineOffer:'Decline the role offer'};
    return form(labels[data.decision],`<p>${['withdraw','declineOffer'].includes(data.decision)?'This ends only this application. Other memberships and plans stay unchanged.':'The applicant will see this message and their next step. Base the decision on the published role; there is no automated ranking.'}</p>${data.decision==='offered'?`<label>Consider the offer through<input type="date" name="offerUntil" required min="${addDays(today(),1)}" max="${addDays(today(),30)}" value="${addDays(today(),7)}"></label><p>A place is reserved until this date. Acceptance starts onboarding; it does not book any work.</p>`:''}<label>${data.decision==='needs-info'?'Your question':'Reason and next step'}<textarea name="note" required maxlength="1200"></textarea></label>`,'Save & share next step',`data-id="${e(data.id)}" data-decision="${e(data.decision)}"`);
  }
  if(type==='Step') {
    const a=r.applications.find(a=>a.id===data.id);const step=onboardingSteps(state,a).find(s=>s.key===data.key);const person=state.people.find(item=>item.id===a.personId);const document=step.documentId&&state.documentLibrary?.items?.find(item=>item.id===step.documentId);
    if(step.completionType==='screening') {
      const coordinator=ui.mode==='coordinator';
      const providerLink=step.attempt?.candidateUrl||step.screening.volunteerUrl;
      const externalLink=(url,label)=>url?`<a class="btn secondary small" href="${e(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
      const screeningForm=(title,formName,body,label)=>({title,content:`<form data-form="${formName}" data-id="${e(a.id)}" data-key="${e(step.key)}"><div class="dialog-body">${body}${errorOutput()}</div><div class="dialog-footer">${button('Cancel','close','','btn secondary')}<button type="submit" class="btn primary">${label}</button></div></form>`});
      if(coordinator&&step.phase==='awaiting-verification')return screeningForm(`Verify ${step.title}`,'rcScreeningVerify',`<p>The volunteer reported completing the external process. Review the result in the provider’s authorized portal before recording a decision here.</p><div class="screening-provider-card"><div><span class="eyebrow">EXTERNAL PROVIDER</span><strong>${e(step.screening.providerName)}</strong></div>${externalLink(step.screening.organizationUrl,'Open review portal')}</div><label>Review outcome<select name="outcome"><option value="satisfied">Requirement satisfied</option><option value="followup">Volunteer follow-up needed</option></select></label><label>Decision note<textarea name="note" required maxlength="600" placeholder="Record the policy basis or next step. Do not copy report details."></textarea></label><label>Valid through<input type="date" name="expiresAt" min="${today()}" value="${addMonths(today(),step.screening.validMonths)}"></label><label class="checkbox-label"><input type="checkbox" name="providerReviewed" required> I reviewed the result in the authorized external system and did not copy sensitive report details into MyCity.</label><p class="microcopy">A satisfied result creates a private MyPassport credential visible to this volunteer. It is not added to their public or organization-shared Passport.</p>`,'Save Review');
      if(coordinator)return screeningForm(`Start ${step.title}`,'rcScreeningStart',`<p>${e(step.detail)}</p><div class="screening-provider-card"><div><span class="eyebrow">EXTERNAL PROVIDER</span><strong>${e(step.screening.providerName)}</strong><small>${step.screening.payer==='organization'?'Organization pays provider':'Volunteer pays provider'}</small></div>${externalLink(step.screening.organizationUrl,'Open provider portal')}</div>${step.screening.startMethod==='organization-invite'?'<label>Candidate invitation link · optional<input type="url" name="candidateUrl" maxlength="500" placeholder="Paste the volunteer-specific link from the provider"></label>':externalLink(step.screening.volunteerUrl,step.screening.startMethod==='live-scan'?'Open Live Scan locations':'Open volunteer start page')}<label>Instructions or note · optional<textarea name="note" maxlength="600" placeholder="What the volunteer should expect next"></textarea></label><label class="checkbox-label"><input type="checkbox" name="invitationSent" required> I sent the provider invitation or the external instructions to the volunteer.</label><p class="microcopy">Identity information and the resulting report stay with ${e(step.screening.providerName)}.</p>`,'Record & Notify Volunteer');
      return screeningForm(step.title,'rcScreeningDeclare',`<p>${e(step.detail)}</p><div class="screening-provider-card"><div><span class="eyebrow">COMPLETE WITH PROVIDER</span><strong>${e(step.screening.providerName)}</strong><small>${step.screening.payer==='organization'?'The organization pays the provider':'You pay the provider directly'}</small></div>${externalLink(providerLink,step.screening.startMethod==='live-scan'?'Find a Live Scan location':'Open provider instructions')}</div>${step.attempt?.note?`<div class="callout sand"><strong>Organization instructions</strong><p>${e(step.attempt.note)}</p></div>`:''}<label>Update for the organization · optional<textarea name="note" maxlength="600" placeholder="For example: completed today or appointment scheduled"></textarea></label><label class="checkbox-label"><input type="checkbox" name="completionConfirmed" required> I completed the provider’s process and understand the organization must verify the result.</label><p class="microcopy">Do not upload or paste a report, Social Security number, fingerprint record, date of birth, ID image, or offense details into MyCity.</p>`,'Send for Verification');
    }
    if(step.completionType==='sign')return form(step.title,`<p>${e(step.detail)}</p>${document?`<div class="activity-waiver-document"><div>${ctx.icon('book')}<span><strong>${e(document.title)}</strong><small>Current version · ${e(document.updatedAt)}</small></span></div>${button('View Document','docOpen',`data-id="${e(document.id)}"`,'btn secondary small')}</div><input type="hidden" name="note" value="Electronically signed ${e(document.title)}."><label>Type your full name<input name="signerName" required autocomplete="name" value="${e(person.name)}"></label><label class="checkbox-label"><input type="checkbox" name="documentAccepted" required> I reviewed this document and agree to sign this version electronically.</label><p class="microcopy">The signature record includes the document, its current version, the signer’s typed name, and the time accepted.</p>`:'<div class="callout sand"><strong>Document unavailable</strong><p>Ask the organization to attach the current document before completing this step.</p></div><input type="hidden" name="note" value="Document unavailable">'}`,'Sign & Complete',`data-id="${e(data.id)}" data-key="${e(data.key)}"`);
    return form(step.title,`<p>${e(step.detail)}</p>${step.key==='welcome'?`<div class="callout sage">${e(orgById(ctx,a.orgId).welcome)}</div>`:''}${document?`<div class="activity-waiver-document"><div>${ctx.icon('book')}<span><strong>${e(document.title)}</strong><small>Current version · ${e(document.updatedAt)}</small></span></div>${button('View Document','docOpen',`data-id="${e(document.id)}"`,'btn secondary small')}</div>`:''}${step.key==='orientation'?'<label>Buddy name<input name="buddy" required maxlength="120"></label><label>Agreed first step<textarea name="firstStep" required maxlength="300" placeholder="A date to choose together, a supervised first task, or a project handoff"></textarea></label>':''}<label>What was completed or discussed?<textarea name="note" required maxlength="1200"></textarea></label><p class="microcopy">This completion is recorded in the shared onboarding history.</p>`,'Record completed step',`data-id="${e(data.id)}" data-key="${e(data.key)}"`);
  }
}
